			db #00, #00, #C6, #6C, #38, #6C, #C6, #00	; 120 x
			db #00, #00, #66, #66, #66, #3E, #06, #7C	; 121 y
			db #00, #00, #7E, #4C, #18, #32, #7E, #00	; 122 z
